const UpsertContactTask = `-- name: UpsertContactTask :one
INSERT INTO contact_task (
    contact_id,
    provider,
    kind,
    lifecycle,
    external_task_id,
    state,
    metadata
) VALUES (
    $1,
    $2,
    $3,
    $4,
    $5,
    COALESCE($6, 'managed'),
    COALESCE($7::jsonb, '{}'::jsonb)
) ON CONFLICT (external_task_id) WHERE external_task_id <> '' DO UPDATE SET
    state = EXCLUDED.state,
    metadata = EXCLUDED.metadata,
    updated_at = NOW()
RETURNING id, contact_id, provider, kind, external_task_id, state, metadata, created_at, updated_at, idempotency_key, lifecycle
`

type UpsertContactTaskParams struct {
	ContactID      pgtype.UUID `json:"contact_id"`
	Provider       string      `json:"provider"`
	Kind           string      `json:"kind"`
	Lifecycle      string      `json:"lifecycle"`
	ExternalTaskID string      `json:"external_task_id"`
	State          interface{} `json:"state"`
	Metadata       []byte      `json:"metadata"`
}

// Upsert a contact task by external_task_id (Todoist task IDs are globally unique)
func (q *Queries) UpsertContactTask(ctx context.Context, arg UpsertContactTaskParams) (*ContactTask, error) {
	row := q.db.QueryRow(ctx, UpsertContactTask,
		arg.ContactID,
		arg.Provider,
		arg.Kind,
		arg.Lifecycle,
		arg.ExternalTaskID,
		arg.State,
		arg.Metadata,
	)
	var i ContactTask
	err := row.Scan(
		&i.ID,
		&i.ContactID,
		&i.Provider,
		&i.Kind,
		&i.ExternalTaskID,
		&i.State,
		&i.Metadata,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.IdempotencyKey,
		&i.Lifecycle,
	)
	return &i, err
}
